var e=[{id:1,text:"¿Cuál es el porcentaje mínimo del horario escolar que deben representar las enseñanzas mínimas en las Comunidades Autónomas con lengua cooficial?",sorted:!1,options:[{text:"60%",correct:!1},{text:"50%",correct:!0},{text:"40%",correct:!1},{text:"65%",correct:!1}]},{id:2,text:"Según la definición de la LOMLOE, ¿qué elemento curricular constituye el nexo de unión entre las competencias clave y los saberes básicos?",sorted:!1,options:[{text:"Los objetivos de etapa",correct:!1},{text:"Los criterios de evaluación",correct:!1},{text:"Las competencias específicas",correct:!0},{text:"El perfil de salida",correct:!1}]},{id:3,text:"¿Cuál es el referente principal utilizado para definir las competencias clave recogidas en el Perfil de salida?",sorted:!1,options:[{text:"La Recomendación del Consejo de la Unión Europea de 22 de mayo de 2018",correct:!0},{text:"Los Objetivos de Desarrollo Sostenible de la Agenda 2015",correct:!1},{text:"El informe Key Drivers of Curricula Change de la UNESCO de 2010",correct:!1},{text:"La Ley Orgánica de Educación de 2006",correct:!1}]},{id:4,text:'En la organización de la Educación Secundaria Obligatoria, ¿en qué momento es obligatorio cursar la materia de "Tecnología y Digitalización"?',sorted:!1,options:[{text:"En todos los cursos del primer ciclo",correct:!1},{text:"En al menos uno de los tres primeros cursos",correct:!0},{text:"Únicamente como materia de opción en cuarto curso",correct:!1},{text:"Como materia optativa a elección del centro en segundo curso",correct:!1}]},{id:5,text:"¿Cuál es la finalidad principal del cuarto curso de la Educación Secundaria Obligatoria?",sorted:!1,options:[{text:"Consolidar únicamente los saberes básicos del primer ciclo",correct:!1},{text:"Carácter orientador para estudios postobligatorios e inserción laboral",correct:!0},{text:"Especialización técnica en una única rama de conocimiento",correct:!1},{text:"Preparación exclusiva para el acceso a ciclos formativos de grado medio",correct:!1}]},{id:6,text:'Dentro de la modalidad de Bachillerato de "Ciencias y Tecnología", ¿qué materia es de oferta obligatoria para el centro en primer curso?',sorted:!1,options:[{text:"Tecnología e Ingeniería I",correct:!1},{text:"Matemáticas I",correct:!0},{text:"Física y Química",correct:!1},{text:"Dibujo Técnico I",correct:!1}]},{id:7,text:'¿Qué definen los "Criterios de Evaluación" en el marco de la LOMLOE?',sorted:!1,options:[{text:"Los contenidos mínimos que el profesor debe impartir en el aula",correct:!1},{text:"Los niveles de desempeño esperados en situaciones vinculadas a competencias específicas",correct:!0},{text:"Las metas que el alumnado debe alcanzar al final de su vida escolar",correct:!1},{text:"El conjunto de métodos pedagógicos aplicados por el docente",correct:!1}]},{id:8,text:"¿Cuál es la permanencia máxima permitida en el régimen ordinario de Bachillerato?",sorted:!1,options:[{text:"Tres años, consecutivos o no",correct:!1},{text:"Cuatro años, consecutivos o no",correct:!0},{text:"Seis años, siempre que sean consecutivos",correct:!1},{text:"Dos años, prorrogables solo por enfermedad",correct:!1}]},{id:9,text:"Bajo la LOMLOE, ¿cómo se denominan los conocimientos, destrezas y actitudes que constituyen los contenidos de un área?",sorted:!1,options:[{text:"Estándares de aprendizaje",correct:!1},{text:"Saberes básicos",correct:!0},{text:"Competencias disciplinares",correct:!1},{text:"Descriptores operativos",correct:!1}]},{id:10,text:'¿En qué modalidad de Bachillerato se integra la materia de "Tecnología e Ingeniería II" en el segundo curso?',sorted:!1,options:[{text:"Artes Plásticas, Imagen y Diseño",correct:!1},{text:"Bachillerato General",correct:!1},{text:"Ciencias y Tecnología",correct:!0},{text:"Humanidades y Ciencias Sociales",correct:!1}]},{id:11,text:"¿Cuál de los siguientes NO es un principio pedagógico de la Educación Secundaria Obligatoria?",sorted:!1,options:[{text:"Fomentar el hábito de la lectura en todas las materias",correct:!1},{text:"Uso exclusivo de lenguas extranjeras en su propio aprendizaje",correct:!0},{text:"Atención a la diversidad y ritmos de aprendizaje",correct:!1},{text:"Promoción del trabajo en equipo y la autonomía",correct:!1}]},{id:12,text:'En el contexto de la LOMLOE, ¿qué son las "Situaciones de Aprendizaje"?',sorted:!1,options:[{text:"Exámenes finales de etapa para obtener el título",correct:!1},{text:"Actividades que implican el despliegue de actuaciones asociadas a competencias",correct:!0},{text:"Periodos de prácticas en empresas para alumnos de secundaria",correct:!1},{text:"Listados de contenidos teóricos que deben ser memorizados",correct:!1}]},{id:13,text:"Para acceder al Bachillerato, ¿qué requisito de titulación es válido además del título de Graduado en ESO?",sorted:!1,options:[{text:"Título de Técnico de Formación Profesional",correct:!0},{text:"Certificado de escolaridad tras finalizar cuarto de ESO sin éxito",correct:!1},{text:"Haber cursado únicamente el primer ciclo de Secundaria",correct:!1},{text:"Título de Educación Primaria y dos años de experiencia laboral",correct:!1}]},{id:14,text:'¿Qué institución tiene la competencia de "desarrollar y completar" los currículos establecidos por las administraciones educativas?',sorted:!1,options:[{text:"El Ministerio de Educación y Formación Profesional",correct:!1},{text:"Los centros docentes",correct:!0},{text:"El Consejo de la Unión Europea",correct:!1},{text:"Las inspecciones educativas únicamente",correct:!1}]},{id:15,text:"En el Bachillerato, ¿qué principio pedagógico se destaca específicamente para favorecer el trabajo del alumnado?",sorted:!1,options:[{text:"La repetición memorística de métodos científicos",correct:!1},{text:"La capacidad para aprender por sí mismo y trabajar en equipo",correct:!0},{text:"La eliminación de la lectura para priorizar el contenido técnico",correct:!1},{text:"El estudio individual aislado para evitar distracciones",correct:!1}]},{id:16,text:"¿A qué edad finaliza, con carácter general, la Educación Secundaria Obligatoria?",sorted:!1,options:[{text:"14 años",correct:!1},{text:"16 años",correct:!0},{text:"18 años",correct:!1},{text:"15 años",correct:!1}]},{id:17,text:"Según el Perfil de salida, ¿qué actitud se debe desarrollar ante la degradación del medioambiente?",sorted:!1,options:[{text:"Una actitud pasiva ante problemas globales",correct:!1},{text:"Una actitud responsable basada en el conocimiento de las causas",correct:!0},{text:"El rechazo total a cualquier tipo de avance tecnológico",correct:!1},{text:"La delegación exclusiva de responsabilidades en las autoridades",correct:!1}]},{id:18,text:'¿En qué curso es obligatorio cursar la materia de "Educación en Valores Cívicos y Éticos"?',sorted:!1,options:[{text:"Solo en segundo de ESO",correct:!1},{text:"En uno de los cuatro cursos de la etapa",correct:!0},{text:"En todos los cursos de Bachillerato",correct:!1},{text:"Únicamente en el último curso de Primaria",correct:!1}]},{id:19,text:'Dentro de la vía de "Música y Artes Escénicas" en Bachillerato, ¿qué materia es de elección obligatoria en primer curso?',sorted:!1,options:[{text:"Análisis Musical I o Artes Escénicas I",correct:!0},{text:"Dibujo Artístico I",correct:!1},{text:"Lenguaje y Práctica Musical",correct:!1},{text:"Coro y Técnica Vocal I",correct:!1}]},{id:20,text:"¿Cómo deben abordar los centros la elección de materias del alumnado si hay pocos solicitantes?",sorted:!1,options:[{text:"Obligando al alumnado a matricularse en centros privados",correct:!1},{text:"Limitando la elección solo bajo criterios objetivos previos",correct:!0},{text:"Suprimiendo la materia sin ofrecer alternativas",correct:!1},{text:"Haciendo un sorteo público entre los interesados",correct:!1}]},{id:21,text:"¿Cuál es uno de los objetivos específicos de la unidad didáctica relacionados con la asignatura de Tecnología?",sorted:!1,options:[{text:"Aprender a programar en lenguajes de alto nivel",correct:!1},{text:"Conocer el proyecto tecnológico y sus fases",correct:!0},{text:"Diseñar circuitos impresos complejos",correct:!1},{text:"Memorizar la historia de la revolución industrial",correct:!1}]},{id:22,text:"¿Qué elemento curricular es común y único para todo el territorio nacional según la LOMLOE?",sorted:!1,options:[{text:"Los saberes básicos de cada materia",correct:!1},{text:"El Perfil de salida del alumnado",correct:!0},{text:"Los métodos pedagógicos de cada centro",correct:!1},{text:"El horario escolar semanal exacto",correct:!1}]},{id:23,text:"En el Bachillerato General, ¿qué materia obligatoria de modalidad se cursa en el segundo año?",sorted:!1,options:[{text:"Ciencias Generales",correct:!0},{text:"Matemáticas Generales",correct:!1},{text:"Economía y Actividad Empresarial",correct:!1},{text:"Historia de España",correct:!1}]},{id:24,text:"¿Cuál es la recomendación horaria de materias en los dos primeros cursos de ESO para favorecer la transición desde Primaria?",sorted:!1,options:[{text:"Cursar el doble de materias que en el ciclo anterior",correct:!1},{text:"Cursar un máximo de una materia más que en el último ciclo de Primaria",correct:!0},{text:"Tener un profesor distinto para cada hora lectiva",correct:!1},{text:"Reducir el horario lectivo a la mitad durante el primer trimestre",correct:!1}]},{id:25,text:"Dentro de los fines de la ESO, ¿qué aspecto se destaca sobre la formación ciudadana?",sorted:!1,options:[{text:"La preparación exclusiva para la inserción laboral inmediata",correct:!1},{text:"Formarlos para el ejercicio de sus derechos y obligaciones",correct:!0},{text:"La competitividad extrema entre individuos del mismo grupo",correct:!1},{text:"El aislamiento de los problemas sociales contemporáneos",correct:!1}]},{id:26,text:'En el Bachillerato de "Humanidades y Ciencias Sociales", ¿qué opción de materia obligatoria tiene el alumno en primer curso?',sorted:!1,options:[{text:"Latín I o Matemáticas Aplicadas a las CCSS I",correct:!0},{text:"Griego I",correct:!1},{text:"Literatura Universal",correct:!1},{text:"Historia del Mundo Contemporáneo",correct:!1}]},{id:27,text:"¿Qué función cumple la unidad creada en el Ministerio de Educación en cooperación con las Comunidades Autónomas?",sorted:!1,options:[{text:"Sustituir a los profesores en huelga",correct:!1},{text:"Contribuir a la actualización permanente de los currículos",correct:!0},{text:"Gestionar los comedores escolares de todo el país",correct:!1},{text:"Diseñar los libros de texto de todas las editoriales",correct:!1}]}],a=[{id:1,text:"¿Cuál es el objetivo primordial de integrar el pensamiento computacional y la robótica dentro del currículo de Tecnología y Digitalización en el 1º ciclo de secundaria?",sorted:!1,options:[{text:"Fomentar la resolución de problemas mediante algoritmos y la automatización de procesos.",correct:!0},{text:"Sustituir el aprendizaje de procesos manuales por el uso exclusivo de entornos digitales.",correct:!1},{text:"Limitar el uso de la tecnología a la creación de aplicaciones para dispositivos móviles.",correct:!1},{text:"Garantizar que el alumnado aprenda a reparar hardware complejo de nivel profesional.",correct:!1}]},{id:2,text:"En el marco de la Competencia Específica 1, ¿qué distingue a la evaluación crítica de la información frente a la simple búsqueda?",sorted:!1,options:[{text:"La capacidad de contrastar fuentes para evaluar la fiabilidad y pertinencia de los datos obtenidos.",correct:!0},{text:"La velocidad con la que se accede a repositorios digitales de datos científicos.",correct:!1},{text:"El uso exclusivo de fuentes primarias impresas para evitar noticias falsas en la red.",correct:!1},{text:"La memorización de los protocolos de transmisión de datos en redes seguras.",correct:!1}]},{id:3,text:"Dentro del proceso tecnológico, ¿cuál es la característica esencial que debe cumplir el problema identificado en la fase inicial?",sorted:!1,options:[{text:"Debe estar acotado para ser resoluble pero suficientemente abierto para permitir diversas soluciones creativas.",correct:!0},{text:"Debe ser estrictamente teórico para garantizar la aplicación del método científico sin errores materiales.",correct:!1},{text:"Debe requerir únicamente los conocimientos previos del alumnado para no depender de la búsqueda externa.",correct:!1},{text:"Debe carecer de restricciones económicas para no limitar la innovación del diseño.",correct:!1}]},{id:4,text:"¿Qué documento del proyecto técnico tiene como función principal detallar las operaciones necesarias para fabricar las piezas?",sorted:!1,options:[{text:"La hoja de procesos.",correct:!0},{text:"La memoria descriptiva.",correct:!1},{text:"El presupuesto detallado.",correct:!1},{text:"El plano de despiece.",correct:!1}]},{id:5,text:"En la fase de verificación y evaluación del proyecto tecnológico, ¿qué acción es obligatoria si el objeto construido no cumple con los requisitos iniciales?",sorted:!1,options:[{text:"Pasar a una fase de rediseño para ajustar el diseño o la construcción.",correct:!0},{text:"Modificar el presupuesto inicial para justificar la falta de funcionalidad.",correct:!1},{text:'Finalizar el proyecto entregando el objeto como "prototipo fallido" para su análisis teórico.',correct:!1},{text:"Ignorar los defectos estéticos siempre que el funcionamiento mecánico sea correcto.",correct:!1}]},{id:6,text:"Al realizar un análisis socioeconómico de un objeto tecnológico, ¿en qué se diferencia fundamentalmente del análisis funcional?",sorted:!1,options:[{text:"El socioeconómico estudia la repercusión social y medioambiental, mientras que el funcional se centra en la utilidad y el manejo.",correct:!0},{text:"El socioeconómico analiza los materiales, mientras que el funcional analiza la historia del objeto.",correct:!1},{text:"El funcional se basa en planos de despiece y el socioeconómico en diagramas de flujo.",correct:!1},{text:"No existe diferencia, ya que la función social es el único motor del diseño tecnológico.",correct:!1}]},{id:7,text:'¿Cuál es la función del "Plano de modificaciones" dentro de la fase de construcción del proyecto tecnológico?',sorted:!1,options:[{text:"Registrar los cambios realizados en el diseño original debido a imprevistos durante la fabricación.",correct:!0},{text:"Autorizar un incremento en el presupuesto por el uso de materiales más caros.",correct:!1},{text:"Sustituir a los bocetos iniciales para ahorrar tiempo en la fase de diseño.",correct:!1},{text:"Servir de guía exclusiva para el alumnado que no participó en la fase de planificación.",correct:!1}]},{id:8,text:"En el contexto de la Competencia Específica 4, ¿qué importancia tiene el uso de vocabulario técnico adecuado en la difusión de ideas?",sorted:!1,options:[{text:"Permite una comunicación precisa y profesional entre los colaboradores del proyecto, ya sea de forma presencial o remota.",correct:!0},{text:"Es un requisito puramente estético para mejorar la calificación del proyecto final.",correct:!1},{text:"Sirve para limitar el acceso a la información tecnológica solo a expertos en la materia.",correct:!1},{text:"Garantiza que el proyecto pueda ser patentado automáticamente a nivel internacional.",correct:!1}]},{id:9,text:"¿A qué bloque de saberes básicos corresponde la configuración y mantenimiento de equipos para optimizar el aprendizaje?",sorted:!1,options:[{text:"Digitalización del entorno personal de aprendizaje.",correct:!0},{text:"Tecnología sostenible.",correct:!1},{text:"Comunicación y difusión de ideas.",correct:!1},{text:"Pensamiento computacional, programación y robótica.",correct:!1}]},{id:10,text:"Según el currículo, ¿qué elemento se considera el eje vertebrador de la materia de Tecnología y Digitalización?",sorted:!1,options:[{text:"El proceso de resolución de problemas.",correct:!0},{text:"El dominio de lenguajes de programación de alto nivel.",correct:!1},{text:"La memorización de la historia de los inventos tecnológicos.",correct:!1},{text:"El uso exclusivo de libros de texto como recurso de aprendizaje.",correct:!1}]},{id:11,text:"En el análisis técnico de un objeto, ¿cuál de los siguientes aspectos es objeto de estudio prioritario?",sorted:!1,options:[{text:"Los principios físicos en los que se basa su funcionamiento y las piezas de unión utilizadas.",correct:!0},{text:"El precio de venta al público en comparación con productos de la competencia.",correct:!1},{text:"La ergonomía y la armonía de los colores del objeto.",correct:!1},{text:"El cumplimiento de las normas de etiqueta digital en su manual de usuario.",correct:!1}]},{id:12,text:"La Competencia Específica 7 subraya la valoración de las tecnologías emergentes. ¿Cuál es su objetivo final?",sorted:!1,options:[{text:"Identificar sus aportaciones al bienestar, a la igualdad social y a la disminución del impacto ambiental.",correct:!0},{text:"Asegurar que el alumnado adquiera las últimas novedades del mercado para evitar la brecha digital.",correct:!1},{text:"Sustituir todas las tecnologías tradicionales por sistemas de inteligencia artificial.",correct:!1},{text:"Eliminar por completo el uso de materiales no reciclables en el aula de tecnología.",correct:!1}]},{id:13,text:'En la Fase de Diseño, ¿qué importancia tiene que la solución sea "la suma de las aportaciones de los miembros del equipo"?',sorted:!1,options:[{text:"Fomenta que todos los alumnos se identifiquen con el resultado y desarrollen actitudes de colaboración.",correct:!0},{text:"Es una estrategia para dividir el trabajo y que cada alumno dibuje solo una parte del objeto.",correct:!1},{text:"Garantiza que el diseño sea más complejo y, por tanto, técnicamente superior.",correct:!1},{text:"Permite que el docente no tenga que intervenir en la resolución de conflictos creativos.",correct:!1}]},{id:14,text:'¿A partir de qué nivel educativo se introducen los "planos de vistas" y "planos en perspectiva" según el contenido del proyecto técnico?',sorted:!1,options:[{text:"3º - 4º de ESO.",correct:!0},{text:"1º ciclo de secundaria.",correct:!1},{text:"Únicamente en Bachillerato.",correct:!1},{text:"Desde Educación Primaria.",correct:!1}]},{id:15,text:"En la Competencia Específica 5, ¿qué papel juega la Inteligencia Artificial (IA) en el desarrollo de aplicaciones?",sorted:!1,options:[{text:"Añadir funcionalidades avanzadas a las soluciones creadas mediante módulos específicos.",correct:!0},{text:"Sustituir la necesidad de aprender algoritmos y diagramas de flujo.",correct:!1},{text:"Automatizar la corrección de errores de seguridad de forma totalmente autónoma.",correct:!1},{text:"Eliminar la interacción humana en los procesos de comunicación digital.",correct:!1}]},{id:16,text:'¿Cuál es la principal diferencia entre un "Proyecto Tecnológico" y un "Proyecto Técnico" según las definiciones proporcionadas?',sorted:!1,options:[{text:"El proyecto tecnológico es el proceso o camino a seguir, mientras que el técnico es la documentación que lo fundamenta.",correct:!0},{text:"El proyecto técnico es exclusivo de ingenieros y el tecnológico es exclusivo de alumnos.",correct:!1},{text:"El proyecto tecnológico no requiere presupuesto y el técnico sí.",correct:!1},{text:"El proyecto técnico se realiza al final de la construcción y el tecnológico al principio.",correct:!1}]},{id:17,text:"En la Competencia Específica 2, ¿qué actitud se espera que el alumnado mantenga ante el diseño de soluciones?",sorted:!1,options:[{text:"Emprendedora, perseverante y creativa.",correct:!0},{text:"Pasiva y receptiva de las instrucciones del docente.",correct:!1},{text:"Competitiva para asegurar que su solución sea la única elegida por el grupo.",correct:!1},{text:"Exclusivamente técnica, ignorando factores estéticos o sociales.",correct:!1}]},{id:18,text:"Al elaborar el presupuesto de un proyecto técnico, ¿qué elemento fiscal se especifica que debe incluirse obligatoriamente?",sorted:!1,options:[{text:"El IVA.",correct:!0},{text:"El IRPF de los componentes del grupo.",correct:!1},{text:"Tasas de importación de componentes electrónicos.",correct:!1},{text:"Un margen de beneficio del 20%.",correct:!1}]},{id:19,text:'¿Cuál es la función del "Estudio Técnico" dentro de la memoria de un proyecto?',sorted:!1,options:[{text:"Analizar la historia, usos, utilidad y relación medioambiental del proyecto.",correct:!0},{text:"Listar exclusivamente las herramientas que se van a usar en el taller.",correct:!1},{text:"Dibujar los bocetos individuales de cada alumno.",correct:!1},{text:"Establecer las normas de seguridad y salud del aula.",correct:!1}]},{id:20,text:'La Competencia Específica 3 menciona la "conformación de materiales". ¿Qué saberes fundamentales deben aplicarse en este proceso?',sorted:!1,options:[{text:"Estructuras, mecanismos, electricidad y electrónica.",correct:!0},{text:"Marketing digital y redes sociales.",correct:!1},{text:"Química orgánica avanzada y biología celular.",correct:!1},{text:"Mecanografía y edición de textos legales.",correct:!1}]},{id:21,text:'¿Qué se entiende por "Propuesta de trabajo" en la segunda fase del proyecto tecnológico?',sorted:!1,options:[{text:"La descripción clara del proyecto y las condiciones iniciales que debe cumplir el objeto.",correct:!0},{text:"Un contrato firmado entre el alumno y el profesor para garantizar la entrega.",correct:!1},{text:"La elección definitiva del material más barato disponible en el almacén.",correct:!1},{text:"El reparto de notas potenciales antes de comenzar la construcción.",correct:!1}]},{id:22,text:'Dentro de la Competencia Específica 6, ¿qué implica hacer un uso "seguro" de los dispositivos digitales?',sorted:!1,options:[{text:"Conocer los riesgos y adoptar medidas para la protección de datos y equipos.",correct:!0},{text:"Utilizar contraseñas sencillas para no olvidarlas nunca.",correct:!1},{text:"No conectar nunca los dispositivos a redes inalámbricas públicas o privadas.",correct:!1},{text:"Permitir que solo el docente configure los ajustes de privacidad de los alumnos.",correct:!1}]},{id:23,text:'En el análisis de objetos, ¿qué se estudia específicamente en el "Análisis Formal"?',sorted:!1,options:[{text:"La forma física del objeto mediante planos, despieces y bocetos.",correct:!0},{text:"El coste de los materiales utilizados en la fabricación.",correct:!1},{text:"Las instrucciones de mantenimiento y riesgos de uso.",correct:!1},{text:"La biografía del inventor que creó el primer prototipo.",correct:!1}]},{id:24,text:"¿Por qué se afirma que la materia de Tecnología y Digitalización contribuye a reducir la brecha de género?",sorted:!1,options:[{text:"Porque fomenta las vocaciones científico-tecnológicas especialmente entre las alumnas mediante la desaparición de estereotipos.",correct:!0},{text:"Porque obliga a que los grupos de trabajo sean siempre exclusivamente femeninos.",correct:!1},{text:"Porque elimina los contenidos de mecánica pesada que tradicionalmente se asociaban a los hombres.",correct:!1},{text:"Porque las evaluaciones son más flexibles para las alumnas que para los alumnos.",correct:!1}]},{id:25,text:"En la Fase de Planificación, ¿qué documentos deben elaborar los alumnos para organizar el trabajo?",sorted:!1,options:[{text:"Lista de materiales, lista de herramientas y asignación de tareas.",correct:!0},{text:"Bocetos individuales y croquis a mano alzada.",correct:!1},{text:"Un resumen de las noticias falsas detectadas durante la investigación.",correct:!1},{text:"El manual de instrucciones de uso para el consumidor final.",correct:!1}]},{id:26,text:'El texto menciona que los centros educativos han pasado de ser "transmisores de conocimientos" a un nuevo rol. ¿Cuál es?',sorted:!1,options:[{text:"Facilitadores de recursos variados para que los alumnos accedan a los contenidos de forma atractiva e interesante.",correct:!0},{text:"Centros de entretenimiento digital donde el alumno decide qué aprender sin guía.",correct:!1},{text:"Exclusivamente talleres de fabricación de objetos sin base teórica previa.",correct:!1},{text:"Bibliotecas digitales donde no existe la interacción física entre alumnos.",correct:!1}]},{id:27,text:"¿Cuál es la última fase del proyecto tecnológico que representa el éxito del proceso?",sorted:!1,options:[{text:"La Solución.",correct:!0},{text:"La construcción del prototipo.",correct:!1},{text:"La entrega de la memoria técnica al profesor.",correct:!1},{text:"El pago de los materiales utilizados en el proyecto.",correct:!1}]},{id:28,text:"¿En cuántos bloques distintos se organizan los saberes básicos de la materia de Tecnología y Digitalización en el primer ciclo de secundaria?",sorted:!1,options:[{text:"4",correct:!1},{text:"5",correct:!0},{text:"6",correct:!1},{text:"7",correct:!1}]},{id:29,text:"¿Cuál es el número total de competencias específicas definidas para la materia de Tecnología y Digitalización?",sorted:!1,options:[{text:"5",correct:!1},{text:"8",correct:!1},{text:"7",correct:!0},{text:"10",correct:!1}]}],t=[{id:1,text:"¿Cuál es la distinción fundamental que establece el currículo entre la alfabetización digital en Primaria y la materia de Digitalización en 4º de ESO?",sorted:!1,options:[{text:"La Primaria se centra en la gestión de identidad, mientras que 4º de ESO busca una ciudadanía digital activa y comprometida.",correct:!0},{text:"La Primaria enseña el hardware y 4º de ESO se dedica exclusivamente a la programación avanzada.",correct:!1},{text:"En Primaria se prohíbe el uso de redes sociales, mientras que en 4º de ESO es el eje central de la materia.",correct:!1},{text:"La diferencia radica únicamente en el uso de herramientas de software libre frente a software propietario.",correct:!1}]},{id:2,text:'Dentro del bloque "Seguridad y bienestar digital", ¿qué aspecto se enfatiza como una amenaza para la salud mental del alumnado?',sorted:!1,options:[{text:"El abuso en los tiempos de conexión y los contenidos inadecuados.",correct:!0},{text:"La falta de actualización de los controladores de hardware.",correct:!1},{text:"El uso exclusivo de licencias Creative Commons.",correct:!1},{text:"La configuración de redes domésticas alámbricas.",correct:!1}]},{id:3,text:"En el contexto de la Competencia Específica 1, ¿qué actitud se requiere del alumno al gestionar redes locales y conectar dispositivos?",sorted:!1,options:[{text:"Una actitud proactiva.",correct:!0},{text:"Una actitud meramente receptiva de las instrucciones del docente.",correct:!1},{text:"Una actitud de rechazo hacia las tecnologías inalámbricas por su inseguridad.",correct:!1},{text:"Una actitud enfocada exclusivamente en el ahorro económico de los componentes.",correct:!1}]},{id:4,text:'Al organizar el aula taller de Tecnología, ¿qué elementos son indispensables en la "zona de trabajo normal" o de exposición?',sorted:!1,options:[{text:"Una pizarra o pantalla de proyección.",correct:!0},{text:"Bancos de trabajo con tornillos de banco.",correct:!1},{text:"Un panel de herramientas manuales organizado por categorías.",correct:!1},{text:"Sistemas de extracción de humos para soldadura.",correct:!1}]},{id:5,text:"¿Cuál es la principal función del profesor durante la fase experimental y de construcción de un proyecto técnico en el aula?",sorted:!1,options:[{text:"Actuar como guía, proporcionando información para que el alumno resuelva problemas sin darle la solución directa.",correct:!0},{text:"Evaluar únicamente el resultado final estético del objeto construido.",correct:!1},{text:"Construir las partes más difíciles del proyecto para asegurar que funcione.",correct:!1},{text:"Impartir una clase magistral continua sobre los principios físicos aplicados.",correct:!1}]},{id:6,text:"Según el INTEF y el Marco de Competencia Digital, ¿en qué área de aprendizaje se incluye el conocimiento sobre derechos de propiedad intelectual y licencias de uso?",sorted:!1,options:[{text:"Área 3: Creación de contenido digital.",correct:!0},{text:"Área 1: Información y alfabetización informacional.",correct:!1},{text:"Área 5: Resolución de problemas.",correct:!1},{text:"Área 2: Comunicación y colaboración.",correct:!1}]},{id:7,text:'¿Cómo se define la técnica de la "Gamificación"?',sorted:!1,options:[{text:"Traslación de la mecánica de los juegos al ámbito educativo-profesional para mejorar resultados.",correct:!0},{text:"Uso exclusivo de videojuegos comerciales durante las horas de clase de Tecnología.",correct:!1},{text:"Creación de un motor gráfico complejo utilizando lenguajes como C++.",correct:!1},{text:"Sustitución de los exámenes tradicionales por torneos de ajedrez.",correct:!1}]},{id:8,text:"¿Cuál es la característica principal del lenguaje de programación Scratch que facilita su difusión educativa?",sorted:!1,options:[{text:"Permite desarrollar habilidades mentales sin necesidad de conocimientos profundos de código textual.",correct:!0},{text:"Es el lenguaje estándar utilizado en la programación de sistemas operativos industriales.",correct:!1},{text:"Requiere un registro obligatorio y pago de licencia anual para su uso en escuelas.",correct:!1},{text:"Se basa en la escritura de comandos complejos para controlar el hardware directamente.",correct:!1}]},{id:9,text:'En pedagogía, ¿qué sostiene la teoría del "Construccionismo" mencionada en relación con Scratch?',sorted:!1,options:[{text:"El conocimiento debe ser construido por el sujeto a través de la acción y la creación de objetos tangibles o digitales.",correct:!0},{text:"El aprendizaje solo ocurre mediante la repetición memorística de manuales técnicos.",correct:!1},{text:"El docente debe ser la única fuente de conocimiento y verdad en el aula.",correct:!1},{text:"La construcción física de robots es irrelevante para el desarrollo cognitivo.",correct:!1}]},{id:10,text:"¿Cuál es una diferencia clave entre la Robótica Educativa (RE) y la Robótica Pedagógica?",sorted:!1,options:[{text:"La RE utiliza kits comerciales a menudo costosos, mientras que la Pedagógica emplea materiales de bajo coste o reciclados.",correct:!0},{text:"La RE se enfoca en la historia de la tecnología y la Pedagógica en la construcción de naves espaciales.",correct:!1},{text:"La Robótica Pedagógica requiere obligatoriamente un ordenador de última generación por alumno.",correct:!1},{text:"La RE prohíbe el uso de sensores y motores para centrarse solo en la estructura física.",correct:!1}]},{id:11,text:"Sobre el equipamiento del aula de robótica, ¿cuál es el número máximo de alumnos recomendado por equipo de trabajo?",sorted:!1,options:[{text:"Cinco alumnos.",correct:!0},{text:"Diez alumnos.",correct:!1},{text:"Dos alumnos obligatoriamente.",correct:!1},{text:"El aula completa funciona como un único equipo.",correct:!1}]},{id:12,text:"¿Qué lenguaje de programación se utiliza específicamente para el kit de robótica Ollo Explorer?",sorted:!1,options:[{text:"RoboPlus.",correct:!0},{text:"Scratch.",correct:!1},{text:"C++ estándar.",correct:!1},{text:"Lenguaje de bloques de Google.",correct:!1}]},{id:13,text:"¿Cuál es la filosofía principal detrás de la plataforma Arduino mencionada en la unidad?",sorted:!1,options:[{text:"Hardware libre y electrónica abierta.",correct:!0},{text:"Software propietario de alta seguridad para aplicaciones bancarias.",correct:!1},{text:"Suscripción mensual obligatoria para acceder a sus bibliotecas.",correct:!1},{text:"Uso exclusivo de componentes de la marca LEGO.",correct:!1}]},{id:14,text:"En el contexto de LEGO Spike Prime, ¿qué significan las siglas STEAM?",sorted:!1,options:[{text:"Science, Technology, Engineering, Art y Mathematics.",correct:!0},{text:"Software, Technical, Electronics, Application y Marketing.",correct:!1},{text:"Sistemas de Tecnología de Energía Atómica y Mecánica.",correct:!1},{text:"Science, Thinking, English, Art y Management.",correct:!1}]},{id:15,text:"¿Qué elemento es fundamental para garantizar la seguridad en el taller de tecnología?",sorted:!1,options:[{text:"El respeto a la señalización de seguridad existente (obligación, peligro, auxilio, prohibición).",correct:!0},{text:"El uso permanente de trajes de protección NBQ.",correct:!1},{text:"La instalación de cámaras de vigilancia en cada banco de trabajo.",correct:!1},{text:"La prohibición total de entrada a alumnos zurdos por el diseño de las máquinas.",correct:!1}]},{id:16,text:"¿Cuál es la recomendación para la composición de los grupos de trabajo en proyectos de Tecnología?",sorted:!1,options:[{text:"Equipos de máximo cuatro personas con funciones rotativas e igualitarias.",correct:!0},{text:"Equipos de una sola persona para fomentar la competitividad extrema.",correct:!1},{text:"Grupos de ocho personas para que el profesor tenga menos grupos que supervisar.",correct:!1},{text:"Equipos divididos estrictamente por género para analizar diferencias en el aprendizaje.",correct:!1}]},{id:17,text:"En el aprendizaje basado en problemas de robótica, ¿cómo cambia el rol del alumno?",sorted:!1,options:[{text:"Pasa de ser un receptor pasivo a ser un pensador activo centrado en resolver el reto.",correct:!0},{text:"Se convierte en un espectador que solo observa cómo el robot se mueve solo.",correct:!1},{text:"Debe memorizar el manual del robot antes de poder tocar las piezas.",correct:!1},{text:"Actúa como un mero operario de fábrica siguiendo órdenes sin cuestionar.",correct:!1}]},{id:18,text:'¿Cuál es el objetivo del bloque de saberes básicos "Ciudadanía digital crítica"?',sorted:!1,options:[{text:"Reflexionar sobre las interacciones en red, considerando la ética, la netiqueta y la propiedad intelectual.",correct:!0},{text:"Enseñar a hackear redes sociales ajenas por motivos de seguridad nacional.",correct:!1},{text:"Obligar a los alumnos a comprar productos exclusivamente en tiendas locales físicas.",correct:!1},{text:"Eliminar cualquier forma de libertad de expresión para evitar conflictos en línea.",correct:!1}]},{id:19,text:'¿Qué componente de hardware se utiliza como el "cerebro" o dispositivo de control en un kit de robótica?',sorted:!1,options:[{text:"Un pequeño ordenador o placa con conectores para sensores y actuadores.",correct:!0},{text:"Un panel solar de gran tamaño para alimentar la red del centro.",correct:!1},{text:"Un motor de rotación continua acoplado a las ruedas.",correct:!1},{text:"Un sensor ultrasónico de proximidad.",correct:!1}]},{id:20,text:"¿Cuál es el enfoque pedagógico de los proyectos de Tecnología propuestos para 4º de ESO?",sorted:!1,options:[{text:"Propuestas con soluciones abiertas y creativas, como el control de un invernadero.",correct:!0},{text:"Construcciones sencillas y cerradas donde el profesor da la única solución posible.",correct:!1},{text:"Análisis exclusivo de la composición química de los plásticos usados en los kits.",correct:!1},{text:"Dibujo artístico de paisajes naturales sin ningún componente técnico.",correct:!1}]},{id:21,text:'En el bloque de "Digitalización del entorno personal de aprendizaje", ¿qué saber se considera fundamental para el aprendizaje permanente?',sorted:!1,options:[{text:"La búsqueda, selección y archivo crítico de información respetando derechos de autor.",correct:!0},{text:"La memorización de las especificaciones de todos los procesadores Intel desde 1980.",correct:!1},{text:"El uso exclusivo de libros de texto en papel para evitar la fatiga visual.",correct:!1},{text:"La desconexión total de internet durante el horario escolar.",correct:!1}]},{id:22,text:'¿Qué kit de robótica está compuesto por piezas de aluminio y se asemeja al clásico "Meccano"?',sorted:!1,options:[{text:"Ollo Explorer Kit.",correct:!0},{text:"Lego Mindstorms.",correct:!1},{text:"Arduino UNO.",correct:!1},{text:"Lego Spike Prime.",correct:!1}]},{id:23,text:"¿Cuál es la función de la zona de herramientas en el aula taller?",sorted:!1,options:[{text:"Dedicada exclusivamente a los trabajos de construcción.",correct:!0},{text:"Espacio para que el profesor duerma durante las clases prácticas.",correct:!1},{text:"Zona de almacenamiento de bocadillos y bebidas para el alumnado.",correct:!1},{text:"Lugar reservado para las clases teóricas de ética digital.",correct:!1}]},{id:24,text:"¿Qué competencia específica se enfoca en el desarrollo de hábitos para proteger la salud y los datos personales?",sorted:!1,options:[{text:"Competencia específica 3.",correct:!0},{text:"Competencia específica 1.",correct:!1},{text:"Competencia específica 4.",correct:!1},{text:"Competencia específica 2.",correct:!1}]},{id:25,text:"¿Por qué es crucial mantener el orden en el taller de tecnología?",sorted:!1,options:[{text:"Para facilitar la ubicación de herramientas y evitar posibles accidentes.",correct:!0},{text:"Para que el aula parezca un museo de arte moderno ante las visitas.",correct:!1},{text:"Para reducir el sueldo del personal de limpieza del centro.",correct:!1},{text:"Para impedir que los alumnos encuentren las herramientas y así no trabajen.",correct:!1}]},{id:26,text:'En el contexto de la programación educativa, ¿qué significa que el aprendizaje sea "lúdico"?',sorted:!1,options:[{text:"Que se basa en el juego y la motivación para introducir conocimientos de forma atractiva.",correct:!0},{text:"Que el profesor no debe corregir los errores para no herir sentimientos.",correct:!1},{text:"Que los alumnos pueden abandonar el aula cuando se aburran.",correct:!1},{text:"Que el contenido curricular se sustituye totalmente por juegos de mesa tradicionales.",correct:!1}]},{id:27,text:"¿Cuántos bloques de saberes básicos componen la materia de Digitalización en 4º de ESO?",sorted:!1,options:[{text:"4",correct:!0},{text:"5",correct:!1},{text:"3",correct:!1},{text:"6",correct:!1}]},{id:28,text:"En el marco de la asignatura de Digitalización, ¿cuál es el número total de competencias específicas establecidas?",sorted:!1,options:[{text:"4",correct:!0},{text:"8",correct:!1},{text:"5",correct:!1},{text:"10",correct:!1}]}],o=[{id:1,text:"¿Cuál de las siguientes afirmaciones describe mejor el eje vertebrador de la asignatura de Tecnología en 4º ESO según el currículo?",sorted:!1,options:[{text:"La resolución de problemas interdisciplinares.",correct:!0},{text:"El dominio técnico de herramientas de fabricación digital.",correct:!1},{text:"El aprendizaje memorístico de operadores tecnológicos.",correct:!1},{text:"La programación exclusiva de dispositivos móviles.",correct:!1}]},{id:2,text:"En el contexto de la Web 3.0, ¿qué función cumplen los metadatos semánticos u ontológicos?",sorted:!1,options:[{text:"Permiten que los datos sean rastreados e interpretados por sistemas de procesamiento de forma eficiente.",correct:!0},{text:"Sirven para aumentar la velocidad de carga de las páginas de solo lectura.",correct:!1},{text:"Son herramientas para que los usuarios finales diseñen gráficos en 3D.",correct:!1},{text:"Actúan como filtros para impedir la interacción social en comunidades virtuales.",correct:!1}]},{id:3,text:"¿Qué criterio diferencia fundamentalmente a la Educación 4.0 de los modelos anteriores en cuanto a la integración de la tecnología?",sorted:!1,options:[{text:"Los objetivos y criterios de evaluación se definen antes de seleccionar las herramientas tecnológicas.",correct:!0},{text:"El uso intensivo de las TIC es el factor que determina por sí solo el éxito del modelo de enseñanza.",correct:!1},{text:"Se prioriza la transmisión unidireccional de contenidos digitales de alta calidad.",correct:!1},{text:"Elimina la necesidad de evaluación continua para centrarse en el juego.",correct:!1}]},{id:4,text:'Dentro del bloque "Pensamiento computacional, automatización y robótica" de 4º ESO, ¿qué elemento se menciona como un valor añadido reciente?',sorted:!1,options:[{text:"La incorporación de módulos de inteligencia artificial y técnicas de ingeniería de datos.",correct:!0},{text:"El uso de herramientas manuales de taller para el montaje de estructuras.",correct:!1},{text:"La sustitución de la programación por el uso de redes sociales.",correct:!1},{text:"El estudio histórico de la evolución de la máquina de vapor.",correct:!1}]},{id:5,text:'De acuerdo con la evolución de la web, ¿qué característica define al "Carácter Beta" de la Web 2.0?',sorted:!1,options:[{text:"La mejora continua de los contenidos y aplicaciones gracias a la participación de los usuarios.",correct:!0},{text:"La restricción del acceso a usuarios con un nivel informático experto.",correct:!1},{text:"La imposibilidad de modificar los datos una vez publicados por el autor.",correct:!1},{text:"El cobro de suscripciones elevadas para mantener la infraestructura.",correct:!1}]},{id:6,text:'¿Cuál es el propósito principal del buscador semántico "Swoogle"?',sorted:!1,options:[{text:"Procesar contenido y realizar deducciones lógicas para resolver problemas cotidianos automáticamente.",correct:!0},{text:"Permitir la creación de blogs educativos sin necesidad de registro.",correct:!1},{text:"Gestionar el almacenamiento en la nube de fotografías de alta resolución.",correct:!1},{text:"Servir como asistente de voz para activar funciones del teléfono móvil.",correct:!1}]},{id:7,text:"En la analogía entre modelos educativos y la web, ¿qué define a la Educación 3.0?",sorted:!1,options:[{text:"Un proceso autodirigido donde los alumnos se convierten en constructores de su propio contenido.",correct:!0},{text:"La adquisición pasiva de información proporcionada exclusivamente por el docente.",correct:!1},{text:"La interacción básica profesor-alumno limitada al aula física.",correct:!1},{text:"El uso de la inteligencia artificial para predecir las notas finales de los estudiantes.",correct:!1}]},{id:8,text:"Según el currículo de Tecnología, ¿qué aspecto debe considerar necesariamente un diseñador para favorecer la inclusión efectiva?",sorted:!1,options:[{text:"La accesibilidad y las diferentes necesidades de la diversidad de personas.",correct:!0},{text:"El coste mínimo de los materiales por encima de su funcionalidad.",correct:!1},{text:"La exclusión de técnicas manuales en favor de procesos automatizados.",correct:!1},{text:"La aplicación de lenguajes de programación complejos y cerrados.",correct:!1}]},{id:9,text:"La Web 4.0, iniciada en 2016, se centra en el desarrollo de sistemas capaces de procesar información de forma similar al cerebro humano mediante:",sorted:!1,options:[{text:"Deep Learning y Machine Learning.",correct:!0},{text:"Hipertextos básicos y archivos GIF.",correct:!1},{text:"El aumento manual de bases de datos por parte de autores individuales.",correct:!1},{text:"La eliminación de los motores de búsqueda en favor de bibliotecas físicas.",correct:!1}]},{id:10,text:"¿Cuál es un inconveniente potencial del uso de la Web 2.0 en el ámbito educativo?",sorted:!1,options:[{text:"El exceso de información y la posibilidad de que esta no siempre sea fiable.",correct:!0},{text:"La necesidad de poseer conocimientos informáticos de nivel ingeniería para usarla.",correct:!1},{text:"La lentitud extrema de los navegadores actuales para procesar texto.",correct:!1},{text:"La falta de herramientas para la comunicación entre individuos.",correct:!1}]},{id:11,text:'El concepto de "Aprender haciendo" en el taller o laboratorio de fabricación de Tecnología busca:',sorted:!1,options:[{text:"Que el alumnado explore, experimente y reflexione mientras materializa proyectos prácticos.",correct:!0},{text:"Sustituir la teoría curricular por la repetición mecánica de tareas de ensamblaje.",correct:!1},{text:"Limitar el uso de ordenadores para volver a la fabricación exclusivamente artesanal.",correct:!1},{text:"Evitar el trabajo en equipo para garantizar la evaluación individual estricta.",correct:!1}]},{id:12,text:"¿Qué herramienta de la Web 2.0 permite el seguimiento de noticias y actualizaciones de sitios favoritos bajo demanda?",sorted:!1,options:[{text:"RSS (Podcast y vodcast).",correct:!0},{text:"Google Maps.",correct:!1},{text:"Sketchup.",correct:!1},{text:"Bdpedia.",correct:!1}]},{id:13,text:"¿Cómo se define la Competencia Específica 3 de la materia de Tecnología en relación con la comunicación?",sorted:!1,options:[{text:"Expresar y difundir soluciones tecnológicas usando lenguaje inclusivo y no sexista para fomentar el trabajo en equipo.",correct:!0},{text:"Dominar exclusivamente el vocabulario técnico en inglés para foros internacionales.",correct:!1},{text:"Utilizar solo esquemas manuales para evitar el uso de herramientas digitales en presentaciones.",correct:!1},{text:"Publicar proyectos sin considerar la adaptación del discurso al público objetivo.",correct:!1}]},{id:14,text:"En el contexto educativo, ¿por qué el aprendizaje memorístico ha dejado de tener sentido según el nuevo paradigma de Internet?",sorted:!1,options:[{text:"Porque Internet pone al alcance cualquier dato de forma inmediata en cualquier momento y lugar.",correct:!0},{text:"Porque la capacidad del cerebro humano ha disminuido debido al uso de smartphones.",correct:!1},{text:"Porque los docentes ya no están capacitados para evaluar exámenes escritos.",correct:!1},{text:"Porque los alumnos ya no están interesados en aprender conceptos científicos.",correct:!1}]},{id:15,text:"¿Qué bloque de saberes básicos aborda la arquitectura bioclimática y el ecotransporte?",sorted:!1,options:[{text:"Tecnología sostenible.",correct:!0},{text:"Operadores tecnológicos.",correct:!1},{text:"Proceso de resolución de problemas.",correct:!1},{text:"Comunidades abiertas de aprendizaje.",correct:!1}]},{id:16,text:'La Web 3.0 es también conocida como la "Data Web" principalmente porque:',sorted:!1,options:[{text:"El usuario tiene el control para modificar directamente las bases de datos de forma inter-operativa.",correct:!0},{text:"Es la primera vez que se utilizan textos y gráficos en los navegadores.",correct:!1},{text:"Se basa únicamente en la cantidad de seguidores en redes sociales.",correct:!1},{text:"Requiere que los datos se guarden obligatoriamente en soportes físicos externos.",correct:!1}]},{id:17,text:"¿Qué herramienta Web 2.0 se describe como un espacio seguro para el aprendizaje activo a través del ensayo y error?",sorted:!1,options:[{text:"Mundos virtuales.",correct:!0},{text:"Wikis.",correct:!1},{text:"Blogger.",correct:!1},{text:"Picasa.",correct:!1}]},{id:18,text:"¿Qué papel juega el docente en el modelo de Educación 2.0?",sorted:!1,options:[{text:"Mediador y orientador de la información.",correct:!0},{text:"Único poseedor y transmisor de la verdad absoluta.",correct:!1},{text:"Creador exclusivo de todos los contenidos que el alumno debe consumir.",correct:!1},{text:"Supervisor de la memorización individual de libros de texto.",correct:!1}]},{id:19,text:'¿Cuál es una característica fundamental de la Web 1.0 que la hace "estática"?',sorted:!1,options:[{text:"El usuario no puede interactuar con el contenido; solo puede leer lo que el autor subió.",correct:!0},{text:"Requiere una conexión de fibra óptica de alta velocidad para funcionar.",correct:!1},{text:"Los contenidos se actualizan automáticamente cada segundo mediante IA.",correct:!1},{text:"Permite que miles de personas editen el mismo archivo simultáneamente.",correct:!1}]},{id:20,text:"¿Qué buscador semántico ofrece representaciones gráficas diferentes para la información en el contexto de la Web 3.0?",sorted:!1,options:[{text:"Wolframalpha.",correct:!0},{text:"Google Now.",correct:!1},{text:"Slideshare.",correct:!1},{text:"Blogger.",correct:!1}]},{id:21,text:'En el currículo de 4º ESO, la competencia de "resolver tareas mediante el uso y configuración de aplicaciones digitales" se asocia a:',sorted:!1,options:[{text:"La Competencia Específica 5.",correct:!0},{text:"La Competencia Específica 1.",correct:!1},{text:"El bloque de Operadores Tecnológicos.",correct:!1},{text:"La Educación 1.0.",correct:!1}]},{id:22,text:'¿Qué se entiende por "personalización" en la Web 3.0?',sorted:!1,options:[{text:"La oferta de contenidos adaptados a los gustos y preferencias del usuario analizando su rastro en la red.",correct:!0},{text:"La capacidad de cambiar el color de fondo de un sitio web manualmente.",correct:!1},{text:"La obligación de usar el nombre real y fotografía en todos los perfiles.",correct:!1},{text:"El diseño de hardware específico para cada estudiante.",correct:!1}]},{id:23,text:'¿Qué cambio de filosofía implica considerar el aprendizaje como un "proceso no necesariamente lineal"?',sorted:!1,options:[{text:"Que el alumno usa los datos que mejor se adecúan a su esquema mental en cada momento.",correct:!0},{text:"Que el profesor debe dictar los apuntes en un orden estrictamente cronológico.",correct:!1},{text:"Que no importa si el alumno aprende o no los contenidos básicos.",correct:!1},{text:"Que el aprendizaje solo debe ocurrir dentro del horario escolar.",correct:!1}]},{id:24,text:'¿Cuál es la función educativa de un "Podcast" de la Web 2.0?',sorted:!1,options:[{text:"Asistir a formación bajo demanda libre de limitaciones espacio-temporales.",correct:!0},{text:"Crear maquetas físicas de circuitos electrónicos en el taller.",correct:!1},{text:"Sustituir la interacción entre alumnos por la escucha pasiva total.",correct:!1},{text:"Impedir que el profesor pueda corregir los errores de los alumnos.",correct:!1}]},{id:25,text:"En la Web 4.0, ¿qué tecnología permitirá conversar con programas (bots) como si fueran amigos en una cafetería?",sorted:!1,options:[{text:"Speech to text (Hablar al texto).",correct:!0},{text:"Escritura manual en código HTML 1.0.",correct:!1},{text:"El uso exclusivo de marcos y framesets.",correct:!1},{text:"La eliminación de la inteligencia artificial de los smartphones.",correct:!1}]},{id:26,text:'El término "Web de las personas" se utiliza para describir la Web 2.0 porque:',sorted:!1,options:[{text:"Transformó la red de un simple depósito de datos en un espacio de integración social y comunicación.",correct:!0},{text:"Significa que la red ha dejado de funcionar con servidores informáticos.",correct:!1},{text:"Indica que solo las personas, y no las empresas, pueden tener páginas web.",correct:!1},{text:"Se refiere a que los ordenadores ahora tienen sentimientos similares a las personas.",correct:!1}]},{id:27,text:"Según el currículo de 4º ESO, ¿qué bloque evalúa la capacidad de integrar el Big Data en sistemas tecnológicos?",sorted:!1,options:[{text:"Pensamiento computacional, automatización y robótica.",correct:!0},{text:"Tecnología sostenible.",correct:!1},{text:"Operadores tecnológicos.",correct:!1},{text:"Proceso de resolución de problemas.",correct:!1}]},{id:28,text:"¿En cuántos bloques de saberes básicos se organiza la materia de Tecnología en el cuarto curso de educación secundaria?",sorted:!1,options:[{text:"3",correct:!1},{text:"4",correct:!0},{text:"5",correct:!1},{text:"6",correct:!1}]},{id:29,text:"¿Cuál es el número total de competencias específicas que orientan el desarrollo de la materia?",sorted:!1,options:[{text:"4",correct:!1},{text:"5",correct:!1},{text:"6",correct:!0},{text:"8",correct:!1}]}],r=[{id:1,text:'¿Cuál es el enfoque principal del bloque de saberes "Sistemas Automáticos" en la asignatura de Tecnología e Ingeniería I?',sorted:!1,options:[{text:"La actualización de sistemas técnicos para su control automático mediante simulación o montaje.",correct:!0},{text:"El estudio pormenorizado de los materiales de nueva generación y su impacto en la industria.",correct:!1},{text:"La programación exclusivamente textual orientada a la creación de aplicaciones móviles.",correct:!1},{text:"La evaluación de mercados energéticos y la eficiencia de la generación eléctrica.",correct:!1}]},{id:2,text:"En el contexto de la competencia específica 1, ¿qué habilidad se busca desarrollar específicamente mediante la iteración en prototipos?",sorted:!1,options:[{text:"La mejora continua de productos viables y socialmente responsables.",correct:!0},{text:"La memorización de terminología técnica para la elaboración de manuales de usuario.",correct:!1},{text:"El cálculo exacto de la eficiencia energética de instalaciones domésticas.",correct:!1},{text:"La selección de materiales tradicionales basándose únicamente en su coste económico.",correct:!1}]},{id:3,text:'Según la definición técnica, ¿cuál es el componente indispensable para que un usuario experimente "Realidad Virtual" (RV)?',sorted:!1,options:[{text:"Un dispositivo de visualización como gafas o casco de realidad virtual.",correct:!0},{text:"Una cámara de alta resolución que capture el entorno real en tiempo real.",correct:!1},{text:"El uso obligatorio de guantes hápticos para la manipulación de objetos.",correct:!1},{text:"Una conexión permanente a un ordenador de alto rendimiento sin batería interna.",correct:!1}]},{id:4,text:"¿Qué diferencia fundamental existe entre la Realidad Aumentada (RA) y la Realidad Mixta (RM) respecto a la interacción con el entorno?",sorted:!1,options:[{text:"La RM permite que objetos físicos del entorno sirvan como elementos de interacción con el entorno virtual.",correct:!0},{text:"La RA aísla completamente al usuario de su entorno físico inmediato.",correct:!1},{text:"La RM solo utiliza imágenes estáticas de 360 grados sin capacidad de movimiento.",correct:!1},{text:"La RA requiere necesariamente el uso de monitores 3D y gafas pasivas.",correct:!1}]},{id:5,text:'¿Cuál es la función principal del sistema "Oculus Insight" presente en las gafas Rift S?',sorted:!1,options:[{text:"Mejorar la detección de movimientos y el rastreo del espacio físico desde el propio visor.",correct:!0},{text:"Permitir la conexión inalámbrica directa con consolas de videojuegos domésticas.",correct:!1},{text:"Sustituir las pantallas internas por proyectores láser directos a la retina.",correct:!1},{text:"Reducir el consumo de batería mediante la desactivación de los sensores de audio.",correct:!1}]},{id:6,text:'En el ámbito de la gamificación, ¿qué diferencia este concepto del "Edutainment"?',sorted:!1,options:[{text:"La gamificación aplica mecánicas de juego en entornos no lúdicos y suele incluir un sistema de recompensas.",correct:!0},{text:"El edutainment prohíbe el uso de tecnología digital en sus procesos de aprendizaje.",correct:!1},{text:"La gamificación se aplica exclusivamente en el marketing y nunca en la educación obligatoria.",correct:!1},{text:'El edutainment requiere que el alumno resuelva retos en sesiones llamadas "Game Jams".',correct:!1}]},{id:7,text:"¿Qué ventaja pedagógica específica se observó en Singapur tras la implementación de viajes de campo virtuales?",sorted:!1,options:[{text:"Las respuestas de los estudiantes en las hojas de trabajo posteriores fueron más perspicaces.",correct:!0},{text:"Se logró sustituir por completo la necesidad de realizar excursiones físicas externas.",correct:!1},{text:"Los alumnos aprendieron a programar robots en primera persona mediante telerobótica.",correct:!1},{text:"Se eliminó el aburrimiento mediante el uso de inteligencia artificial adaptativa.",correct:!1}]},{id:8,text:'¿Cuál es la característica distintiva de la plataforma "zSpace" en comparación con los auriculares de RV tradicionales?',sorted:!1,options:[{text:"Utiliza monitores y gafas similares a las del cine 3D para evitar el aislamiento social.",correct:!0},{text:"Consiste en una plataforma de cartón plegable que funciona con smartphones Android.",correct:!1},{text:"Se basa en una camiseta virtual que permite ver el interior del cuerpo humano.",correct:!1},{text:"Ofrece un laboratorio de química virtual donde se manipula mercurio y plomo sin riesgo.",correct:!1}]},{id:9,text:'Dentro del bloque "Materiales y fabricación", ¿qué aspecto se considera crítico para una fabricación de productos de calidad?',sorted:!1,options:[{text:"La determinación del ciclo de vida del producto y la aplicación de medidas de control de calidad.",correct:!0},{text:"La utilización exclusiva de materiales plásticos por su facilidad de moldeado.",correct:!1},{text:"El uso de lenguajes de programación textual para el control de la maquinaria.",correct:!1},{text:"La eliminación de cualquier fase de prototipado para acelerar la salida al mercado.",correct:!1}]},{id:10,text:'¿Qué propósito tienen los llamados "Serious Games" en el entorno educativo?',sorted:!1,options:[{text:"Diseñar juegos con un propósito formativo que va más allá del puro entretenimiento.",correct:!0},{text:"Crear competiciones de e-sports entre centros educativos para fomentar el deporte.",correct:!1},{text:"Sustituir las clases teóricas por sesiones de juego libre sin supervisión docente.",correct:!1},{text:"Desarrollar aplicaciones que solo funcionen en dispositivos de gama alta como HTC Vive.",correct:!1}]},{id:11,text:"En el estudio de Common Sense Media, ¿cuál fue uno de los principales obstáculos identificados para la adopción doméstica de la RV?",sorted:!1,options:[{text:"El precio elevado de los dispositivos y el desconocimiento de la tecnología.",correct:!0},{text:"La falta de aplicaciones educativas en idiomas distintos al inglés.",correct:!1},{text:"La obligatoriedad de tener un espacio de más de 20 metros cuadrados para jugar.",correct:!1},{text:"La interferencia de las ondas de radio de la RV con otros electrodomésticos.",correct:!1}]},{id:12,text:"¿Cómo contribuye la asignatura de Tecnología e Ingeniería a mitigar las desigualdades sociales según el currículo?",sorted:!1,options:[{text:"Evitando generar nuevas brechas cognitivas, de género o generacionales mediante el acceso a saberes técnicos.",correct:!0},{text:"Fomentando la exportación de materias primas a países desarrollados para mejorar la economía.",correct:!1},{text:"Haciendo obligatoria la compra de kits de realidad virtual para todos los alumnos.",correct:!1},{text:"Centrándose únicamente en el desarrollo de software para empresas multinacionales.",correct:!1}]},{id:13,text:'¿Qué funcionalidad específica ofrece la aplicación "Curiscope" para el estudio de la anatomía?',sorted:!1,options:[{text:"Permite visualizar el interior del cuerpo humano al escanear una camiseta especial con un smartphone.",correct:!0},{text:"Proporciona una simulación de cirugía en 3D utilizando mandos de control táctil.",correct:!1},{text:"Crea un avatar digital del alumno que realiza ejercicio físico en un gimnasio virtual.",correct:!1},{text:"Genera informes médicos automáticos basados en el ritmo cardíaco detectado por el móvil.",correct:!1}]},{id:14,text:'¿Cuál es el objetivo del bloque de saberes "Tecnología Sostenible"?',sorted:!1,options:[{text:"Alinear la materia con las metas de los Objetivos de Desarrollo Sostenible (ODS).",correct:!0},{text:"Estudiar la historia de la revolución industrial y sus principales inventores.",correct:!1},{text:"Aprender a fabricar componentes electrónicos utilizando metales pesados.",correct:!1},{text:"Desarrollar campañas de marketing para vender productos tecnológicos obsoletos.",correct:!1}]},{id:15,text:'¿Qué capacidad diferencia al "Oculus Quest" de los modelos anteriores de la misma marca?',sorted:!1,options:[{text:"Es un sistema inalámbrico e independiente que no requiere conexión a un ordenador.",correct:!0},{text:"Ofrece la posibilidad de ver el entorno real sin quitarse el casco.",correct:!1},{text:"Incluye sensores externos de gran tamaño que deben instalarse en las esquinas de la habitación.",correct:!1},{text:"Es el único dispositivo compatible con aplicaciones de Google Expeditions.",correct:!1}]},{id:16,text:"¿Qué metodología de trabajo se propone como eje vertebrador en la asignatura de Tecnología e Ingeniería?",sorted:!1,options:[{text:"La resolución de problemas interdisciplinares mediante el método de proyectos.",correct:!0},{text:"El estudio individual basado en la lectura intensiva de manuales técnicos antiguos.",correct:!1},{text:"La realización de exámenes semanales de opción múltiple sin componente práctico.",correct:!1},{text:"La competición individualista para obtener la patente de invención más rentable.",correct:!1}]},{id:17,text:'En el contexto de la RV en educación, ¿qué permite la "telerobótica"?',sorted:!1,options:[{text:"Experimentar en primera persona las acciones de un robot gestionado a distancia.",correct:!0},{text:"Reparar averías eléctricas en el hogar mediante el uso de comandos de voz.",correct:!1},{text:"Sustituir al profesor por un bot de inteligencia artificial que imparte la lección.",correct:!1},{text:"Traducir instantáneamente textos antiguos del latín al lenguaje de programación C++.",correct:!1}]},{id:18,text:'¿Cuál es la premisa económica de "Google Cardboard"?',sorted:!1,options:[{text:"Transformar cualquier smartphone en una plataforma de RV por un coste inferior a 5 dólares.",correct:!0},{text:"Ofrecer un descuento del 50% en la compra de ordenadores de alta gama para escuelas.",correct:!1},{text:"Vender kits de construcción de ordenadores hechos íntegramente de material reciclado.",correct:!1},{text:"Financiar el desarrollo de videojuegos triple A para dispositivos Android.",correct:!1}]},{id:19,text:"Según el currículo, ¿qué se debe considerar al abordar la existencia de un producto?",sorted:!1,options:[{text:"Todo lo que implica su creación, su ciclo de vida y su impacto industrial.",correct:!0},{text:"Únicamente el margen de beneficio neto tras su venta en mercados internacionales.",correct:!1},{text:"El color y la estética del empaquetado para atraer al consumidor infantil.",correct:!1},{text:"La posibilidad de que el producto sea fabricado exclusivamente por robots sin intervención humana.",correct:!1}]},{id:20,text:"Dentro de la Competencia Específica 3, ¿cuál es el criterio para el uso de herramientas digitales?",sorted:!1,options:[{text:"Utilizarlas de manera óptima y autónoma para resolver tareas y presentar resultados.",correct:!0},{text:"Limitar su uso a una hora diaria para evitar la adicción a las pantallas.",correct:!1},{text:"Usar solo redes sociales para difundir noticias sobre el cambio climático.",correct:!1},{text:"Eliminar el uso de papel en todas las fases del proyecto de investigación.",correct:!1}]},{id:21,text:'¿Qué permite la aplicación "Discovery VR" a sus usuarios?',sorted:!1,options:[{text:"Experimentar los programas favoritos de la cadena de una manera completamente nueva e inmersiva.",correct:!0},{text:"Grabar y editar sus propios documentales de naturaleza en resolución 8K.",correct:!1},{text:"Chatear en tiempo real con exploradores que se encuentran en expediciones reales.",correct:!1},{text:"Comprar animales exóticos a través de un mercado virtual integrado.",correct:!1}]},{id:22,text:'¿Cuál es una de las metas del bloque "Materiales y fabricación" respecto a la sostenibilidad?',sorted:!1,options:[{text:"Elaborar soluciones tecnológicas sostenibles mediante técnicas de transformación apropiadas.",correct:!0},{text:"Reducir el coste de fabricación mediante el uso de mano de obra no cualificada.",correct:!1},{text:"Fabricar únicamente productos que tengan una vida útil inferior a un año.",correct:!1},{text:"Ignorar el impacto ambiental si el material seleccionado es estéticamente superior.",correct:!1}]},{id:23,text:'¿Qué papel juega el "error" en el proceso iterativo mencionado en el criterio de evaluación 1.2?',sorted:!1,options:[{text:"Es una oportunidad para identificar mejoras y optimizar el prototipo de forma continua.",correct:!0},{text:"Es motivo de suspenso inmediato en la asignatura de Tecnología e Ingeniería.",correct:!1},{text:"Debe ocultarse en la documentación técnica para no perjudicar la imagen del proyecto.",correct:!1},{text:"Solo se permite si el alumno utiliza herramientas manuales en lugar de digitales.",correct:!1}]},{id:24,text:"En el contexto de la Competencia Específica 5, ¿qué tecnologías emergentes se mencionan como herramientas de control?",sorted:!1,options:[{text:"Inteligencia artificial, internet de las cosas y big data.",correct:!0},{text:"Telegrafía sin hilos y motores de vapor de baja presión.",correct:!1},{text:"Diseño de moda digital y edición de blogs de viajes.",correct:!1},{text:"Únicamente la programación en bloques para niños de primaria.",correct:!1}]},{id:25,text:'¿Qué finalidad tiene el bloque "Sistemas mecánicos" en el desarrollo de proyectos?',sorted:!1,options:[{text:"Servir de base para la realización de proyectos mediante elementos de transmisión y transformación de movimientos.",correct:!0},{text:"Estudiar la composición química detallada de los lubricantes sintéticos.",correct:!1},{text:"Analizar la evolución de la literatura de ciencia ficción en el siglo XX.",correct:!1},{text:"Sustituir todos los motores eléctricos por sistemas de poleas manuales para ahorrar energía.",correct:!1}]},{id:26,text:"Según el informe de TwoReality, ¿qué gran empresa ha desarrollado aplicaciones de RV orientadas específicamente a la formación?",sorted:!1,options:[{text:"Disney.",correct:!0},{text:"Nintendo.",correct:!1},{text:"Ford.",correct:!1},{text:"Coca-Cola.",correct:!1}]},{id:27,text:"¿En cuántos bloques de saberes básicos se articula la materia de Tecnología e Ingeniería I?",sorted:!1,options:[{text:"4",correct:!1},{text:"6",correct:!1},{text:"8",correct:!1},{text:"7",correct:!0}]},{id:28,text:"¿Cuántas competencias específicas definen los objetivos de aprendizaje en la asignatura de Tecnología e Ingeniería I?",sorted:!1,options:[{text:"4",correct:!1},{text:"5",correct:!1},{text:"6",correct:!0},{text:"7",correct:!1}]}],i=[{id:1,text:"¿En qué se diferencia el enfoque de la asignatura Tecnología e Ingeniería II respecto a la de primer curso de Bachillerato?",sorted:!1,options:[{text:"Se centra específicamente en el análisis de necesidades y la resolución de problemas mediante innovación y emprendimiento.",correct:!0},{text:"Abandona los fundamentos científicos para centrarse únicamente en la técnica manual del taller.",correct:!1},{text:"Sustituye el trabajo en equipo por la investigación puramente teórica e individual.",correct:!1},{text:"Se limita exclusivamente al estudio de la historia de la ingeniería y los inventos clásicos.",correct:!1}]},{id:2,text:"Dentro de la Competencia Específica 1, ¿qué papel juega el error en el proceso de aprendizaje del alumno?",sorted:!1,options:[{text:"Se utiliza como un elemento constructivo que permite aprender de la crítica razonada y gestionar la incertidumbre.",correct:!0},{text:"Debe evitarse mediante el uso exclusivo de simuladores que impidan resultados incorrectos.",correct:!1},{text:"Se penaliza estrictamente para fomentar la precisión absoluta en la documentación técnica.",correct:!1},{text:"Es irrelevante siempre que el producto final funcione correctamente en la presentación.",correct:!1}]},{id:3,text:"Para cumplir con el criterio de evaluación 2.1, ¿qué aspecto de los materiales técnicos debe analizar prioritariamente el estudiante?",sorted:!1,options:[{text:"Su estructura interna y tratamientos de modificación para garantizar la sostenibilidad y calidad.",correct:!0},{text:"Únicamente su coste de mercado para maximizar el beneficio económico del proyecto.",correct:!1},{text:"Su apariencia estética para asegurar la aceptación comercial inmediata del producto.",correct:!1},{text:"La disponibilidad de stock en grandes superficies comerciales locales.",correct:!1}]},{id:4,text:"En el ámbito de las máquinas térmicas (Competencia 4), ¿cuál de los siguientes es un requisito de evaluación específico?",sorted:!1,options:[{text:"Realizar cálculos básicos sobre la eficiencia y simular el funcionamiento de bombas de calor.",correct:!0},{text:"Diseñar combustibles alternativos de alta octanaje para motores de combustión interna.",correct:!1},{text:"Memorizar los diagramas de fases de todos los gases refrigerantes industriales.",correct:!1},{text:"Construir un motor térmico real utilizando materiales reciclados del aula.",correct:!1}]},{id:5,text:"Al trabajar con electrónica digital según el currículo de 2º de Bachillerato, ¿qué distinción deben experimentar los alumnos?",sorted:!1,options:[{text:"La diferencia funcional entre circuitos combinacionales y secuenciales mediante montajes físicos o simulados.",correct:!0},{text:"El uso exclusivo de lógica difusa para el control de procesos industriales pesados.",correct:!1},{text:"La soldadura manual de microchips de alta integración sin apoyo de software.",correct:!1},{text:"La programación única en lenguaje ensamblador para todos los proyectos.",correct:!1}]},{id:6,text:"¿Cuál es un objetivo crítico de la Competencia Específica 5 respecto a los sistemas automáticos?",sorted:!1,options:[{text:"Simular procesos basados en lazo abierto y cerrado analizando su estabilidad y técnicas de simplificación.",correct:!0},{text:"Eliminar todos los sistemas de lazo cerrado por ser excesivamente complejos para el aula.",correct:!1},{text:"Centrarse únicamente en el control manual para evitar el uso de tecnologías emergentes.",correct:!1},{text:"Ignorar la seguridad de los datos al ser sistemas puramente mecánicos.",correct:!1}]},{id:7,text:"¿Cómo afectan las brechas de género al desarrollo del impacto de la Ciencia, Tecnología e Innovación (CTI)?",sorted:!1,options:[{text:"Limitan la participación plena de las mujeres y reducen el impacto potencial de la CTI en el desarrollo económico.",correct:!0},{text:"Aumentan la eficiencia de la investigación al especializar a cada género en tareas distintas.",correct:!1},{text:"Son irrelevantes en la fase de generación de evidencia y trabajo de campo.",correct:!1},{text:"Se resuelven automáticamente al aumentar el financiamiento global sin intervención social.",correct:!1}]},{id:8,text:'¿A qué se refiere la fuente cuando menciona que los artefactos tecnológicos están "marcados por el género"?',sorted:!1,options:[{text:"A que la tecnología es una construcción social realizada predominantemente por hombres, lo que puede excluir perspectivas femeninas.",correct:!0},{text:"A que existen herramientas con colores específicos destinados a hombres y mujeres.",correct:!1},{text:"A que las leyes de la física cambian según quién opere el dispositivo.",correct:!1},{text:"A que los manuales de instrucciones deben estar escritos en lenguaje inclusivo obligatoriamente.",correct:!1}]},{id:9,text:'Según el informe "Perspectivas", ¿cuál es la tendencia general actual de la educación frente al futuro?',sorted:!1,options:[{text:"Fundamentarse más en el conocimiento tradicional que en la previsión sistemática del futuro.",correct:!0},{text:"Abandonar completamente los contenidos clásicos por el uso de realidad virtual inmediata.",correct:!1},{text:"Sustituir al profesorado por sistemas de Inteligencia Artificial para 2026.",correct:!1},{text:"Limitar el uso de internet para proteger a los alumnos de las tecnoadicciones.",correct:!1}]},{id:10,text:'¿Qué caracteriza a la "Segunda Etapa" de innovación en las aulas españolas (2021-2026) según el Gabinete de Comunicación y Educación de la UAB?',sorted:!1,options:[{text:"La emergencia de espacios destinados al intercambio y a la producción mediante impresoras 3D, robótica e IA.",correct:!0},{text:"La sustitución básica de la pizarra de tiza por pantallas digitales interactivas.",correct:!1},{text:'El cambio total de las metodologías didácticas hacia el modelo de "Aula del Futuro".',correct:!1},{text:'La prohibición de dispositivos móviles personales para asegurar el modelo "One to One".',correct:!1}]},{id:11,text:'En el modelo de "Aula del Futuro", ¿qué se busca potenciar al zonificar el espacio?',sorted:!1,options:[{text:"El desarrollo de habilidades y competencias en los alumnos por encima de la mera adquisición de contenidos.",correct:!0},{text:"La vigilancia estricta de los alumnos para evitar que utilicen dispositivos no autorizados.",correct:!1},{text:"El ahorro de espacio físico para poder albergar a un mayor número de estudiantes por aula.",correct:!1},{text:"La especialización de cada alumno en una sola tarea técnica durante todo el curso.",correct:!1}]},{id:12,text:'¿Cuál es la función específica de la zona "Investiga" en el Aula del Futuro del INTEF?',sorted:!1,options:[{text:"Fomentar el pensamiento computacional y la búsqueda activa de información mediante materiales específicos.",correct:!0},{text:"Servir como rincón de descanso y ocio digital para los alumnos que terminan rápido sus tareas.",correct:!1},{text:"Es el único lugar donde el profesor tiene permitido dar una lección magistral tradicional.",correct:!1},{text:"Almacenar los servidores y el equipamiento de red del centro educativo.",correct:!1}]},{id:13,text:'Al implementar la metodología "Flipped Classroom", ¿cómo se transforma el tiempo en el aula?',sorted:!1,options:[{text:"Se convierte en un tiempo para la acción y la construcción colaborativa del conocimiento.",correct:!0},{text:"Se dedica exclusivamente a la lectura individual y silenciosa de los libros de texto.",correct:!1},{text:"Se reduce a la mitad para permitir que los alumnos pasen más tiempo en casa con sus familias.",correct:!1},{text:"Se utiliza para realizar exámenes diarios y controlar que el alumno estudió en su hogar.",correct:!1}]},{id:14,text:"¿Qué herramienta del INTEF funciona como una red social de recursos educativos abiertos vinculada con tecnología semántica?",sorted:!1,options:[{text:"Espacio Procomún.",correct:!0},{text:"Observatorio de Tecnología Educativa.",correct:!1},{text:"Plan de Cultura Digital.",correct:!1},{text:"Red de Embajadores Aula del Futuro.",correct:!1}]},{id:15,text:"En el Observatorio de Tecnología Educativa, ¿qué contenido diferencial encontraría un docente?",sorted:!1,options:[{text:"Artículos creados por docentes para docentes con aplicaciones didácticas y valoraciones reales.",correct:!0},{text:"Anuncios publicitarios de las últimas novedades en hardware comercial.",correct:!1},{text:"Listados de calificaciones de alumnos a nivel nacional.",correct:!1},{text:"Códigos de programación para hackear sistemas de gestión escolar.",correct:!1}]},{id:16,text:'A pesar de ser considerados "nativos digitales", ¿de qué carecen habitualmente los menores según el texto de tecnoadicciones?',sorted:!1,options:[{text:"Conocimientos sobre seguridad, privacidad, legislación y uso responsable de las herramientas.",correct:!0},{text:"Capacidad motriz para pulsar los botones de una tablet o smartphone.",correct:!1},{text:"Acceso a internet en los centros educativos públicos españoles.",correct:!1},{text:"Interés por los videojuegos en línea o la mensajería instantánea.",correct:!1}]},{id:17,text:"¿Qué dato estadístico destaca a España en el contexto europeo de conductas adictivas a internet?",sorted:!1,options:[{text:'Es el país con el mayor porcentaje de jóvenes "en riesgo" de desarrollar conductas adictivas (21,3%).',correct:!0},{text:"Es el país con menor uso diario de redes sociales en adolescentes.",correct:!1},{text:"Solo un 5% de los jóvenes descuida sus actividades por estar conectado.",correct:!1},{text:"Las tecnoadicciones solo afectan a los adultos mayores de 40 años.",correct:!1}]},{id:18,text:"Para que el uso de las TIC se considere una adicción, ¿cuál de estos síntomas es un indicador clave según la Fundación Mapfre?",sorted:!1,options:[{text:"La incapacidad de controlar el tiempo de conexión y la necesidad de aumentar este tiempo para sentirse satisfecho.",correct:!0},{text:"Utilizar el ordenador media hora al día para hacer los deberes de clase.",correct:!1},{text:"Tener un perfil en una red social profesional para buscar empleo.",correct:!1},{text:"Preferir jugar al fútbol con amigos en el parque en lugar de jugar a la consola.",correct:!1}]},{id:19,text:"Si un profesor sospecha que un alumno tiene una tecnoadicción por su cansancio y bajo rendimiento, ¿cuál debe ser el primer paso?",sorted:!1,options:[{text:"Hablar con otros profesores y compañeros para confirmar la percepción antes de que intervenga el orientador.",correct:!0},{text:"Expulsar al alumno inmediatamente del aula para proteger al resto del grupo.",correct:!1},{text:"Publicar el caso en las redes sociales del centro para alertar a otros padres.",correct:!1},{text:"Confiscar el smartphone del alumno de forma permanente sin avisar a la familia.",correct:!1}]},{id:20,text:"En el contexto de la estabilidad de estructuras (Comp. 4), ¿qué debe ser capaz de interpretar el alumno?",sorted:!1,options:[{text:"Los tipos de cargas a las que se ven sometidas y su estabilidad mediante cálculos o montajes.",correct:!0},{text:"El valor estético de los monumentos históricos de la ciudad.",correct:!1},{text:"La biografía de los arquitectos más famosos del siglo XIX.",correct:!1},{text:"El precio de las pólizas de seguro para rascacielos comerciales.",correct:!1}]},{id:21,text:"¿Qué diferencia define a la Conducta Adictiva a Internet (CAI)?",sorted:!1,options:[{text:"Un patrón caracterizado por la pérdida de control que conduce al aislamiento y descuido de la salud e higiene.",correct:!0},{text:"Estar suscrito a más de tres plataformas de streaming simultáneamente.",correct:!1},{text:"Utilizar internet exclusivamente para buscar información académica rigurosa.",correct:!1},{text:"Poseer más de dos dispositivos electrónicos en la habitación.",correct:!1}]},{id:22,text:'Según el modelo "Aula del Futuro", ¿qué herramientas facilitan el aprendizaje directo mediante la experiencia directa con el entorno?',sorted:!1,options:[{text:"Geo-localización y Realidad Aumentada.",correct:!0},{text:"Calculadoras científicas de bolsillo.",correct:!1},{text:"Libros de texto en formato PDF estático.",correct:!1},{text:"Pizarras de tiza verde tradicionales.",correct:!1}]},{id:23,text:'¿Qué organismo europeo originó el proyecto que hoy conocemos en España como "Aula del Futuro"?',sorted:!1,options:[{text:"European Schoolnet (EUN).",correct:!0},{text:"Agencia Espacial Europea (ESA).",correct:!1},{text:"Organización Mundial del Comercio (OMC).",correct:!1},{text:"Fondo Monetario Internacional (FMI).",correct:!1}]},{id:24,text:"Al analizar la eficiencia de los procesos de fabricación (Comp. 6), ¿bajo qué enfoque debe hacerlo el alumno?",sorted:!1,options:[{text:"Responsabilidad social y sostenibilidad energética.",correct:!0},{text:"Velocidad máxima de producción sin importar el residuo generado.",correct:!1},{text:"Uso exclusivo de mano de obra barata para reducir costes fijos.",correct:!1},{text:"Obsolecencia programada para garantizar ventas futuras.",correct:!1}]},{id:25,text:'¿En qué consiste la zona "Crea" del Aula del Futuro?',sorted:!1,options:[{text:"Un espacio dotado con estudio de grabación y herramientas para producir contenidos audiovisuales.",correct:!0},{text:"Un área destinada únicamente a la pintura al óleo sobre lienzo.",correct:!1},{text:"Es el lugar donde se guardan los exámenes finales bajo llave.",correct:!1},{text:"Un taller de carpintería tradicional sin dispositivos electrónicos.",correct:!1}]},{id:26,text:"Dentro del estudio de circuitos de corriente alterna (Comp. 4), ¿cuál es el objetivo final?",sorted:!1,options:[{text:"Identificar sus elementos y comprender su funcionamiento mediante montajes o simulaciones.",correct:!0},{text:"Rediseñar la red eléctrica nacional de alta tensión de forma individual.",correct:!1},{text:"Prohibir el uso de corriente alterna por ser más peligrosa que la continua.",correct:!1},{text:"Aprender a manipular cables de alta tensión sin equipo de protección.",correct:!1}]},{id:27,text:"¿En cuántos bloques de saberes básicos se articula la materia de Tecnología e Ingeniería II?",sorted:!1,options:[{text:"4",correct:!1},{text:"6",correct:!1},{text:"8",correct:!1},{text:"7",correct:!0}]},{id:28,text:"¿Cuántas competencias específicas definen los objetivos de aprendizaje en la asignatura de Tecnología e Ingeniería II?",sorted:!1,options:[{text:"4",correct:!1},{text:"5",correct:!1},{text:"6",correct:!0},{text:"7",correct:!1}]}];export{e as CCD_UD1_QUESTIONS,a as CCD_UD2_QUESTIONS,t as CCD_UD3_QUESTIONS,o as CCD_UD4_QUESTIONS,r as CCD_UD5_QUESTIONS,i as CCD_UD6_QUESTIONS};